const deliveredStatus=messages=>{const user=[...messages].reverse().find(item=>item.role==='user'&&item.content.includes('Current Gmail status at this provider dispatch: '));assert.ok(user,'Missing current Gmail dispatch status');const json=user.content.split('Current Gmail status at this provider dispatch: ').at(-1).split('\n')[0];return JSON.parse(json).gmailConnectionAtDelivery.status;};
const restoredGrant=async(f,grant)=>{const target=(await f.call('/api/secret-grant-targets')).value.find(item=>item.integration==='gmail.client');const result=await f.call('/api/secret-grants/grant',{name:grant.name,revision:grant.revision,integration:target.integration,destination:target.destination,version:target.version,previous:target.current,confirm:true,confirmDisplacement:false});assert.equal(result.status,200,JSON.stringify(result.value));};

test('provider initialization observes restored grants and disconnected accounts in every mode',async()=>{
 for(const mode of ['direct','hybrid','code'])for(const change of ['restore','disconnect']){let active=false,release,entered;const gate=new Promise(resolve=>release=resolve),started=new Promise(resolve=>entered=resolve),f=await fixture(mode,{initialize:async()=>{if(active){entered();await gate;}}});try{const route=`/api/question-sets/${f.q.id}`,preview=(await f.call(route+'/gmail-preview')).value,start=await f.call(route+'/gmail-start',{...preview,confirm:true,confirmDisplacements:false});assert.equal((await fetch(callback(start.value.url))).status,200);const grant=(await f.call('/api/secret-grants')).value.find(item=>item.integration==='gmail.client');if(change==='restore')assert.equal((await f.call('/api/secret-grants/revoke',{...grant,confirm:true})).status,200);active=true;const resolved=await f.call(route+'/submit',{});assert.equal(resolved.value.result.gmailAuthorization,'previously_succeeded');await started;if(change==='restore')await restoredGrant(f,grant);else assert.equal((await f.call('/api/plugins/gmail/disconnect',{})).status,200);const expected=change==='restore'?'credentials_available':'disconnected';assert.equal((await f.call('/api/question-sets')).value.find(item=>item.id===f.q.id).gmailConnection.status,expected);release();await wait(async()=>(await f.call('/api/question-sets')).value.find(item=>item.id===f.q.id).continuationState==='completed');const messages=JSON.parse(f.seen.findLast(text=>text.includes('Owner response to question set')));assert.equal(deliveredStatus(messages),expected);assert.ok(JSON.stringify(messages).includes('previously_succeeded'));assert.ok(!JSON.stringify(messages).includes(secret));await f.restart();const q=(await f.call('/api/question-sets')).value.find(item=>item.id===f.q.id);assert.equal(q.result.gmailAuthorization,'previously_succeeded');assert.equal(q.gmailConnection.status,expected);}finally{release();await f.close();}}
});

test('background Gmail results refresh after an adapter waits before sending',async()=>{
 for(const mode of ['direct','hybrid','code']){let release,entered;const gate=new Promise(resolve=>release=resolve),started=new Promise(resolve=>entered=resolve);let held=false;const f=await fixture(mode,{task:true,beforeSend:async(messages,opts)=>{if(!held && messages.some(item=>item.role==='tool'&&item.content.includes('previously_succeeded'))){held=true;entered();await gate;}return opts.refreshMessages?.()??messages;}});try{const route=`/api/question-sets/${f.q.id}`,preview=(await f.call(route+'/gmail-preview')).value,start=await f.call(route+'/gmail-start',{...preview,confirm:true,confirmDisplacements:false});assert.equal((await fetch(callback(start.value.url))).status,200);const result=await f.call(route+'/submit',{});assert.equal(result.value.result.gmailAuthorization,'previously_succeeded');assert.equal(result.value.result.gmailConnectionAtResolution.status,'credentials_available');await started;const grant=(await f.call('/api/secret-grants')).value.find(item=>item.integration==='gmail.client');await f.call('/api/secret-grants/revoke',{...grant,confirm:true});release();await wait(async()=>(await f.call('/api/tasks/setup')).value.state==='completed');const input=JSON.parse(f.seen.findLast(text=>text.includes('previously_succeeded')));assert.equal(deliveredStatus(input),'credentials_unavailable');assert.ok(!JSON.stringify(input).includes(secret));await f.restart();assert.equal((await f.call('/api/question-sets')).value.find(item=>item.id===f.q.id).result.gmailAuthorization,'previously_succeeded');}finally{release();await f.close();}}
});

test('each follow-up provider call refreshes Gmail availability for chat and task work',async()=>{
 for(const kind of ['command','task'])for(const mode of ['direct','hybrid','code']){let release,entered,sentTool=false,held=false;const gate=new Promise(resolve=>release=resolve),started=new Promise(resolve=>entered=resolve);const f=await fixture(mode,{task:kind==='task',beforeSend:async(messages,opts)=>{const latest=messages.findLastIndex(item=>item.role==='user'),after=messages.slice(latest+1);if(sentTool && !held && after.some(item=>item.role==='tool'&&item.content.includes('items'))){held=true;entered();await gate;}return opts.refreshMessages?.()??messages;},respond:async(messages)=>{const relevant=messages.some(item=>item.role==='user'&&item.content.includes('Current Gmail status at this provider dispatch'));if(relevant && !sentTool){sentTool=true;const call=mode==='code'?{name:'code_mode',arguments:JSON.stringify({source:'return await capabilities.memory_search({scope:{kind:"agent"},query:""});'})}:{name:'memory_search',arguments:JSON.stringify({scope:{kind:'agent'},query:''})};return {role:'assistant',content:null,tool_calls:[{id:'read-memory',type:'function',function:call}]};}}});try{const route=`/api/question-sets/${f.q.id}`,preview=(await f.call(route+'/gmail-preview')).value,start=await f.call(route+'/gmail-start',{...preview,confirm:true,confirmDisplacements:false});assert.equal((await fetch(callback(start.value.url))).status,200);await f.call(route+'/submit',{});await started;const grant=(await f.call('/api/secret-grants')).value.find(item=>item.integration==='gmail.client');await f.call('/api/secret-grants/revoke',{...grant,confirm:true});release();if(kind==='task')await wait(async()=>(await f.call('/api/tasks/setup')).value.state==='completed');else await wait(async()=>(await f.call('/api/question-sets')).value.find(item=>item.id===f.q.id).continuationState==='completed');const calls=f.seen.map(text=>JSON.parse(text)).filter(messages=>messages.some(item=>item.role==='user'&&item.content.includes('Current Gmail status at this provider dispatch')));assert.equal(calls.length,2);assert.equal(deliveredStatus(calls[0]),'credentials_available');assert.equal(deliveredStatus(calls[1]),'credentials_unavailable');assert.ok(!JSON.stringify(calls).includes(secret));}finally{release();await f.close();}}
});

test('later chat turns refresh Gmail status without rewriting the historical result',async()=>{
 for(const mode of ['direct','hybrid','code']){const f=await fixture(mode);try{const route=`/api/question-sets/${f.q.id}`,preview=(await f.call(route+'/gmail-preview')).value,start=await f.call(route+'/gmail-start',{...preview,confirm:true,confirmDisplacements:false});assert.equal((await fetch(callback(start.value.url))).status,200);const resolved=await f.call(route+'/submit',{});await wait(async()=>(await f.call('/api/question-sets')).value.find(item=>item.id===f.q.id).continuationState==='completed');const grant=(await f.call('/api/secret-grants')).value.find(item=>item.integration==='gmail.client');await f.call('/api/secret-grants/revoke',{...grant,confirm:true});assert.equal((await f.call('/api/commands',{id:'later',botId:f.bot.id,content:'Check my previous setup'})).status,200);await wait(async()=>(await f.call('/api/commands/later')).value.state==='completed');let input=JSON.parse(f.seen.at(-1));assert.equal(deliveredStatus(input),'credentials_unavailable');assert.ok(JSON.stringify(input).includes('previously_succeeded'));assert.equal((await f.call('/api/question-sets')).value.find(item=>item.id===f.q.id).result.gmailConnectionAtResolution.status,resolved.value.result.gmailConnectionAtResolution.status);await restoredGrant(f,grant);assert.equal((await f.call('/api/commands',{id:'later-again',botId:f.bot.id,content:'Check again'})).status,200);await wait(async()=>(await f.call('/api/commands/later-again')).value.state==='completed');input=JSON.parse(f.seen.at(-1));assert.equal(deliveredStatus(input),'credentials_available');assert.ok(!JSON.stringify(input).includes(secret));}finally{await f.close();}}
});

test('restart while a continuation provider initializes interrupts rather than sends stale status',async()=>{
 let active=false,release,entered;const gate=new Promise(resolve=>release=resolve),started=new Promise(resolve=>entered=resolve),f=await fixture('direct',{initialize:async()=>{if(active){entered();await gate;}}});try{const route=`/api/question-sets/${f.q.id}`,preview=(await f.call(route+'/gmail-preview')).value,start=await f.call(route+'/gmail-start',{...preview,confirm:true,confirmDisplacements:false});assert.equal((await fetch(callback(start.value.url))).status,200);active=true;await f.call(route+'/submit',{});await started;const grant=(await f.call('/api/secret-grants')).value.find(item=>item.integration==='gmail.client');await f.call('/api/secret-grants/revoke',{...grant,confirm:true});await f.restart();release();const q=(await f.call('/api/question-sets')).value.find(item=>item.id===f.q.id);assert.equal(q.continuationState,'interrupted');assert.equal(q.gmailConnection.status,'credentials_unavailable');assert.equal(q.result.gmailAuthorization,'previously_succeeded');assert.ok(!f.seen.some(text=>text.includes('Owner response to question set')));}finally{release();await f.close();}
});

test('older persisted delivery snapshots are not replayed as current status',async()=>{
 const f=await fixture();try{const route=`/api/question-sets/${f.q.id}`,preview=(await f.call(route+'/gmail-preview')).value,start=await f.call(route+'/gmail-start',{...preview,confirm:true,confirmDisplacements:false});assert.equal((await fetch(callback(start.value.url))).status,200);await f.call(route+'/submit',{});await wait(async()=>(await f.call('/api/question-sets')).value.find(item=>item.id===f.q.id).continuationState==='completed');const grant=(await f.call('/api/secret-grants')).value.find(item=>item.integration==='gmail.client');await f.call('/api/secret-grants/revoke',{...grant,confirm:true});await f.restart(()=>{const db=new DatabaseSync(f.path),row=db.prepare('SELECT session FROM sessions WHERE bot_id=?').get(f.bot.id),session=JSON.parse(row.session),prior=session.messages.find(item=>item.role==='user'&&item.content.includes('Owner response to question set'));assert.ok(prior);const lines=prior.content.split('\n'),outcome=JSON.parse(lines[1]);outcome.gmailConnectionAtDelivery={status:'credentials_available',enabled:false};lines[1]=JSON.stringify(outcome);prior.content=lines.join('\n');db.prepare('UPDATE sessions SET session=? WHERE bot_id=?').run(JSON.stringify(session),f.bot.id);db.close();});await f.call('/api/commands',{id:'after-old-result',botId:f.bot.id,content:'Review the earlier setup'});await wait(async()=>(await f.call('/api/commands/after-old-result')).value.state==='completed');const input=JSON.parse(f.seen.at(-1)),old=input.find(item=>item.role==='user'&&item.content.includes('Owner response to question set'));assert.equal(old.content.includes('gmailConnectionAtDelivery'),false);assert.equal(deliveredStatus(input),'credentials_unavailable');assert.ok(JSON.stringify(input).includes('previously_succeeded'));await f.restart(()=>{const db=new DatabaseSync(f.path,{readOnly:true});assert.ok(String(db.prepare('SELECT session FROM sessions WHERE bot_id=?').get(f.bot.id).session).includes('gmailConnectionAtDelivery'));db.close();});}finally{await f.close();}
});

test('uncertain credential transition interrupts a waiting continuation before model dispatch',async()=>{
 let active=false,fault=false,release,entered;const gate=new Promise(resolve=>release=resolve),started=new Promise(resolve=>entered=resolve),f=await fixture('direct',{initialize:async()=>{if(active){entered();await gate;}},credentialTransition:(kind,stage)=>{if(fault && kind==='gmail' && stage==='after-commit')throw Error('Synthetic uncertain transition');}});try{const route=`/api/question-sets/${f.q.id}`,preview=(await f.call(route+'/gmail-preview')).value,start=await f.call(route+'/gmail-start',{...preview,confirm:true,confirmDisplacements:false});assert.equal((await fetch(callback(start.value.url))).status,200);active=true;await f.call(route+'/submit',{});await started;const review=(await f.call('/api/secret-setup-review?integration=gmail')).value;fault=true;const attempt=await f.call('/api/plugins/gmail/start',{email:'owner@example.test',clientId:'new-client',clientSecret:'synthetic-replacement-client',confirm:true,reviewedVersion:review.version,confirmDisplacements:true});assert.equal(attempt.status,200,JSON.stringify(attempt.value));assert.equal((await fetch(callback(attempt.value.url))).status,400);const q=(await f.call('/api/question-sets')).value.find(item=>item.id===f.q.id);assert.equal(q.gmailConnection.status,'unknown');release();await wait(async()=>(await f.call('/api/commands/'+q.continuationId)).value.state!=='pending');assert.ok(!f.seen.some(text=>text.includes('Owner response to question set')));fault=false;await f.restart();const restored=(await f.call('/api/question-sets')).value.find(item=>item.id===f.q.id);assert.equal(restored.result.gmailAuthorization,'previously_succeeded');assert.equal(restored.gmailConnection.status,'credentials_available');assert.ok(!JSON.stringify(f.seen).includes('synthetic-replacement-client'));}finally{release();await f.close();}
});
